async page => {
  const results = [];
  const reset = async () => { await page.getByRole('button', { name: 'Reset fixture', exact: true }).click(); await page.waitForTimeout(80); };
  await page.setViewportSize({ width: 1440, height: 1000 }); await reset();
  const split = page.getByRole('separator', { name: '调整左右分栏比例' });
  await split.focus(); await page.keyboard.press('Home');
  const leftPane = await page.locator('[data-pane-id="alpha"]').boundingBox();
  results.push({ check: 'keyboard-minimum-pane-width', width: leftPane.width, expectedMinimum: 100, pass: leftPane.width >= 99 });
  await reset();
  await page.setViewportSize({ width: 800, height: 900 });
  results.push(await page.locator('[data-workspace-sidebar="right"]').evaluate(frame => ({ check: 'narrow-right-sidebar', frameWidth: frame.getBoundingClientRect().width, contentDisplay: getComputedStyle(frame.querySelector('.right-sidebar')).display, pass: getComputedStyle(frame.querySelector('.right-sidebar')).display !== 'none' || frame.getBoundingClientRect().width === 0 })));
  await page.setViewportSize({ width: 1600, height: 1000 }); await reset();
  const leftSeparator = page.getByRole('separator', { name: '调整左侧栏宽度' });
  await leftSeparator.focus(); await page.keyboard.press('End');
  await page.setViewportSize({ width: 1000, height: 1000 });
  const beforeKeyboard = await page.locator('[data-workspace-sidebar="left"]').boundingBox();
  await leftSeparator.focus(); await page.keyboard.press('ArrowLeft');
  const afterKeyboard = await page.locator('[data-workspace-sidebar="left"]').boundingBox();
  results.push({ check: 'sidebar-keyboard-after-viewport-shrink', before: beforeKeyboard.width, after: afterKeyboard.width, expectedChange: -10, pass: Math.abs(afterKeyboard.width - beforeKeyboard.width + 10) <= 2 });
  const before = await page.locator('[data-workspace-sidebar="left"]').boundingBox();
  const handle = await leftSeparator.boundingBox();
  await page.mouse.move(handle.x + handle.width / 2, handle.y + 200); await page.mouse.down(); await page.mouse.move(handle.x + handle.width / 2 - 20, handle.y + 200, { steps: 8 }); await page.mouse.up();
  const after = await page.locator('[data-workspace-sidebar="left"]').boundingBox();
  results.push({ check: 'sidebar-resize-after-viewport-shrink', before: before.width, after: after.width, expectedChange: -20, pass: Math.abs(after.width - before.width + 20) <= 2 });
  await page.setViewportSize({ width: 1440, height: 1000 }); await reset();
  for (let index = 0; index < 3; index++) await page.getByRole('button', { name: 'Split below beta', exact: true }).click();
  const shortPane = page.locator('[data-pane-id="beta"]');
  const shortBox = await shortPane.boundingBox(), start = await page.getByRole('button', { name: 'Tab Alpha.md', exact: true }).boundingBox();
  const tabbarBox = await shortPane.locator('.tabbar').boundingBox();
  const dropX = shortBox.x + shortBox.width / 2, dropY = tabbarBox.y + tabbarBox.height + 4;
  await page.mouse.move(start.x + start.width / 2, start.y + start.height / 2); await page.mouse.down();
  await page.mouse.move(start.x + start.width / 2 + 14, start.y + start.height / 2 + 14, { steps: 4 });
  await page.mouse.move(dropX, dropY, { steps: 15 }); await page.mouse.move(dropX + 1, dropY + 1); await page.waitForTimeout(80); await page.mouse.up(); await page.waitForTimeout(80);
  const workspace = JSON.parse(await page.locator('#workspace-state').textContent());
  const moved = workspace.panes.find(pane => pane.id !== 'alpha' && pane.tabs.includes('Alpha.md'));
  const movedBox = moved ? await page.locator(`[data-pane-id="${moved.id}"]`).boundingBox() : null;
  const remainingBox = await shortPane.boundingBox();
  results.push({ check: 'short-pane-top-docking', originalHeight: shortBox.height, count: workspace.panes.length, movedAboveTarget: movedBox && movedBox.y < remainingBox.y, pass: shortBox.height < 175 && workspace.panes.length === 6 && movedBox?.y < remainingBox.y });
  await reset();
  return results;
}
